    ) -> Option<WorldVec2> {
        self.active_skill_casts
            .get(&cast_seq)
            .and_then(|cast_state| cast_state.cast_target_anchor_world_position)
    }

    fn cleanup_finished_skill_cast(&mut self, cast_seq: u64) {
        let size = self
            .active_skill_casts
            .get(&cast_seq)
            .map_or(0, |cast| cast.step_progress.len());
        if control::charge(size as u64 + 1, "cast_cleanup_scan").is_err() {
            return;
        }
        let should_remove = self
            .active_skill_casts
            .get(&cast_seq)
            .is_some_and(|cast_state| {
                cast_state.deferred_steps.is_empty()
                    && cast_state.active_area_ids.is_empty()
                    && cast_state.step_progress.len() == cast_state.total_steps
                    && cast_state
                        .step_progress
                        .values()
                        .all(SkillStepProgress::is_terminal)
            });

        if should_remove {
            self.active_skill_casts.remove(&cast_seq);
        }
    }

    pub(in crate::game::battle::core) fn begin_skill_step_delivery(
        &mut self,
        cast_seq: u64,
        step_index: usize,
        delivery_count: usize,
    ) {
        let growth = usize::from(
            self.active_skill_casts
                .get(&cast_seq)
                .is_some_and(|cast| !cast.step_progress.contains_key(&step_index)),
        );
        if self
            .admit_authoring_runtime_growth(growth, "cast_child_record")
            .is_err()
        {
            return;
        }
        let Some(cast_state) = self.active_skill_casts.get_mut(&cast_seq) else {
            return;
        };

        let progress = cast_state
            .step_progress
            .entry(step_index)
            .or_insert_with(|| SkillStepProgress {
                result: SkillStepResult::default(),
                started: true,
                pending_delivery_count: 0,
            });
        progress.started = true;
        progress.pending_delivery_count = progress
            .pending_delivery_count
            .saturating_add(delivery_count);
    }

    pub(in crate::game::battle::core) fn record_skill_step_result(
        &mut self,
        cast_seq: u64,
        step_index: usize,
        result: SkillStepResult,
    ) {
        let growth = usize::from(
            self.active_skill_casts
                .get(&cast_seq)
                .is_some_and(|cast| !cast.step_progress.contains_key(&step_index)),
        );
        if self
            .admit_authoring_runtime_growth(growth, "cast_child_record")
            .is_err()
        {
            return;
        }
        let Some(cast_state) = self.active_skill_casts.get_mut(&cast_seq) else {
            return;
        };

        let progress = cast_state
            .step_progress
            .entry(step_index)
            .or_insert_with(|| SkillStepProgress {
                result: SkillStepResult::default(),
                started: true,
                pending_delivery_count: 0,
            });
        progress.started = true;
        progress.result.merge(&result);
    }

    pub(in crate::game::battle::core) fn finalize_skill_step(
        &mut self,
        cast_seq: u64,
        step_index: usize,
        result: SkillStepResult,
        time_ms: u64,
    ) {
        self.record_skill_step_result(cast_seq, step_index, result);
        if control::poll("skill_result_recorded").is_err() {
            return;
        }
        if let Some(cast_state) = self.active_skill_casts.get_mut(&cast_seq) {
            let progress = cast_state
                .step_progress
                .entry(step_index)
                .or_insert_with(|| SkillStepProgress {
                    result: SkillStepResult::default(),
                    started: true,
                    pending_delivery_count: 0,
                });
            progress.started = true;
            progress.pending_delivery_count = 0;
        }
        self.release_deferred_skill_steps(cast_seq, time_ms);
        self.cleanup_finished_skill_cast(cast_seq);
    }

    pub(in crate::game::battle::core) fn resolve_skill_step_delivery(
        &mut self,
        cast_seq: u64,
        step_index: usize,
        result: SkillStepResult,
        terminal: bool,
        time_ms: u64,
    ) {
        self.record_skill_step_result(cast_seq, step_index, result);
        if control::poll("skill_result_recorded").is_err() {
            return;
        }

        if let Some(cast_state) = self.active_skill_casts.get_mut(&cast_seq) {
            let progress = cast_state
                .step_progress
                .entry(step_index)
                .or_insert_with(|| SkillStepProgress {
                    result: SkillStepResult::default(),
                    started: true,
                    pending_delivery_count: usize::from(!terminal),
                });
            progress.started = true;
            if terminal && progress.pending_delivery_count > 0 {
                progress.pending_delivery_count -= 1;
            }
        }

        self.release_deferred_skill_steps(cast_seq, time_ms);
        self.cleanup_finished_skill_cast(cast_seq);
    }

    pub(in crate::game::battle::core) fn defer_skill_step(
        &mut self,
        cast_seq: u64,
        step_index: usize,
        deferred: DeferredSkillStep,
    ) {
        let growth = usize::from(
            self.active_skill_casts
                .get(&cast_seq)
                .is_some_and(|cast| !cast.deferred_steps.contains_key(&step_index)),
        );

    if let Some(unit) = self.units.get_mut(&target_id) {
        unit.pending_cast = false;
        unit.pending_cast_cause = None;
    }

    self.record_event_log(
        current_time_ms,
        BattleLogEvent::SkillCastInterrupted {
            interrupter_instance_id: source_id,
            caster_instance_id: target_id,
            interrupted_skill_id: pending.skill_id,
            interrupted_cast_seq: pending.start_seq,
        },
    );
}
BattleCommand::ApplyHeal {
    target_id,
    flat,
    percent,
    source_id,
} => {
    let max_health = match self.units.get(&target_id) {
        Some(unit) if unit.is_active() => unit.stats.max_health.max(1),
        _ => continue,
    };

    let percent_delta = (i64::from(max_health) * i64::from(percent)) / 100;
    let delta_i64 = i64::from(flat).saturating_add(percent_delta);
    let delta = delta_i64.clamp(i64::from(i32::MIN), i64::from(i32::MAX)) as i32;
    let hp_before = self
        .units
        .get(&target_id)
        .map(|unit| unit.stats.current_health)
        .unwrap_or(0);

    self.apply_hp_delta_and_record(
        source_id,
        target_id,
        delta,
        current_time_ms,
        HpChangeReason::Command,
    );

    let hp_after = self
        .units
        .get(&target_id)
        .map(|unit| unit.stats.current_health)
        .unwrap_or(hp_before);
    if hp_after < hp_before {
        summary.actual_damage_target_count =
            summary.actual_damage_target_count.saturating_add(1);
    }
}
