pub(in crate::game::battle::core) fn deploy_player_unit(

        withdrawn_unit_id: UnitInstanceId,
    ) {
        let mut expired = self
            .buffs
            .keys()
            .copied()
            .filter_map(|key| {
                if key.target_instance_id == withdrawn_unit_id {
                    Some((key, BuffExpireReason::TargetWithdrawn))
                } else if key.caster_instance_id == withdrawn_unit_id {
                    Some((key, BuffExpireReason::CasterWithdrawn))
                } else {
                    None
                }
            })
            .collect::<Vec<_>>();
        expired.sort_by(|(left_key, left_reason), (right_key, right_reason)| {
            left_key
                .target_instance_id
                .cmp(&right_key.target_instance_id)
                .then_with(|| {
                    left_key
                        .caster_instance_id
                        .cmp(&right_key.caster_instance_id)
                })
                .then_with(|| left_key.buff_id.as_u64().cmp(&right_key.buff_id.as_u64()))
                .then_with(|| (*left_reason as u8).cmp(&(*right_reason as u8)))
        });
        for (key, reason) in expired {
            if self.buffs.remove(&key).is_none() {
                continue;
            }
            self.record_event_log(
                time_ms,
                BattleLogEvent::BuffExpired {
                    caster_instance_id: key.caster_instance_id,
                    target_instance_id: key.target_instance_id,
                    buff_id: key.buff_id,
                    reason,
                },
            );
        }
    }

    fn cancel_active_skill_runtime_for_withdrawn_unit(
        &mut self,
        time_ms: u64,
        withdrawn_unit_id: UnitInstanceId,
    ) {
        let mut cancelled_casts = self
            .active_skill_casts
            .iter()
            .filter_map(|(cast_seq, cast)| {
                (cast.caster_instance_id == withdrawn_unit_id).then_some((
                    *cast_seq,
                    cast.ability_event_seq,
                    cast.skill_id.clone(),
                ))
            })
            .collect::<Vec<_>>();
        cancelled_casts.sort_by_key(|(cast_seq, _, _)| *cast_seq);

        for (cast_seq, ability_event_seq, skill_id) in cancelled_casts {
            if self.active_skill_casts.remove(&cast_seq).is_none() {
                continue;
            }
            self.record_event_log(
                time_ms,
                BattleLogEvent::SkillCastCancelled {
                    caster_instance_id: withdrawn_unit_id,
                    interrupted_skill_id: skill_id,
                    interrupted_cast_seq: ability_event_seq,
                    reason: SkillCastCancelReason::Withdrawn,
                },
            );
        }

        self.active_areas.retain(|_, area| {
            area.caster_instance_id != withdrawn_unit_id
                || matches!(area.tracking, SkillAreaTracking::GroundFixed)
        });
    }

    fn record_pending_skill_cast_cancelled_for_withdrawn_unit(
        &mut self,
        time_ms: u64,
        withdrawn_unit_id: UnitInstanceId,
        pending_skill_cast: Option<crate::game::battle::core::types::PendingSkillCast>,
    ) {
        let Some(pending) = pending_skill_cast else {
            return;
        };
        self.record_event_log(
            time_ms,
            BattleLogEvent::SkillCastCancelled {
                caster_instance_id: withdrawn_unit_id,
                interrupted_skill_id: pending.skill_id,
                interrupted_cast_seq: pending.start_seq,
                reason: SkillCastCancelReason::Withdrawn,
            },
        );
    }
}

fn invoke_ability_with_accepted_target_tile(
    &mut self,
    time_ms: u64,
    caster_instance_id: UnitInstanceId,
    skill_id: &str,
    target_snapshot: (Option<SkillCastTarget>, Option<Position>),
    cause: BattleEventCause,
    allow_dead_caster: bool,
) {
    let (explicit_target, accepted_target_tile) = target_snapshot;
    let Ok(Some(skill)) = self.cloned_skill_definition(skill_id) else {
        return;
    };

    let Some((caster_owner, caster_pos)) =
        self.resolve_cast_origin_context(None, caster_instance_id, allow_dead_caster)
    else {
        return;
    };
    let cast_target = explicit_target.or_else(|| {
        self.resolve_skill_cast_target_at(
            time_ms,
            &skill,
            caster_instance_id,
            caster_owner,
            caster_pos,
        )
    });

    let target_instance_id = match cast_target {
        Some(SkillCastTarget::Unit { unit_instance_id }) => Some(unit_instance_id),
        _ => None,
    };
    let cast_target_anchor_position = accepted_target_tile.or_else(|| match cast_target {
        Some(SkillCastTarget::Tile { position }) => Some(position),
        Some(SkillCastTarget::Unit { unit_instance_id }) => {
            self.live_unit_projected_tile(unit_instance_id)
        }
        None => None,
    });
    let cast_target_anchor_world_position = accepted_target_tile
        .map(crate::game::battle::core::movement::types::WorldVec2::from_tile_center)
        .or_else(|| match cast_target {
            Some(SkillCastTarget::Tile { position }) => Some(
                crate::game::battle::core::movement::types::WorldVec2::from_tile_center(
                    position,
                ),
            ),
            Some(SkillCastTarget::Unit { unit_instance_id }) => {
                self.unit_world_position_or_tile_center(unit_instance_id)
            }
            None => None,
        });

    if self
        .admit_authoring_runtime_growth(1, "skill_cast_spawn")
        .is_err()
    {
        return;
    }
    let cast_seq = self.skill_cast_seq;
    self.skill_cast_seq = self.skill_cast_seq.wrapping_add(1);
    let ability_event_seq = self.with_recording_context(cause, |core| {
        core.record_event_log(
            time_ms,
            BattleLogEvent::AbilityCast {
                skill_id: skill.id.clone(),
                caster_instance_id,
                target_instance_id,
            },
        )
    });

    self.active_skill_casts.insert(
        cast_seq,
        super::types::ActiveSkillCast {
            execution_source: Some(std::sync::Arc::new(
                crate::game::battle::skill_source::SkillCastExecutionSource {
                    skill_id: skill.id.clone(),
                    caster_instance_id,
                    cast_seq,
                    ability_event_seq,
                    cause,
                    proc_origin: self.recording_skill_proc_origin.clone(),
                },
            )),
            caster_instance_id,
            ability_event_seq,
            skill_id: skill.id.clone(),
            caster_owner,
            anchor_position: caster_pos,
            cast_target_anchor_position,
            cast_target_anchor_world_position,
            allow_dead_caster,
            total_steps: skill.steps.len(),
            step_progress: Default::default(),
            deferred_steps: Default::default(),
            impact_contexts_by_step: Default::default(),
            last_impact_context: None,
            active_area_ids: Vec::new(),
        },
    );

    self.with_recording_cause(ability_event_seq, |core| {
        for (step_index, step) in skill.steps.iter().enumerate() {
            if control::charge(1, "skill_step_enqueue").is_err() {
                return;
            }
            core.event_queue.push(BattleEvent::SkillStep {
                time_ms: time_ms.saturating_add(step.delay_ms as u64),
                cast_seq,
                step_index,
                caster_instance_id,
                skill_id: skill.id.clone(),
                step_id: step.id.clone(),
                cast_target,
                cause: BattleEventCause::Parent {
                    seq: ability_event_seq,
                },
            });
        }
    });
}

pub(super) fn start_manual_skill_cast(
    &mut self,
    time_ms: u64,
    caster_instance_id: UnitInstanceId,
    requested_skill_id: SkillId,
    explicit_target: Option<SkillCastTarget>,
) -> Result<(), GameError> {
    let (skill, cast_target) = self.resolve_manual_skill_cast_request(
        time_ms,
        caster_instance_id,
        &requested_skill_id,
        explicit_target,
    )?;

    let cast_end_ms = if skill.focus_time_ms == 0 {
        time_ms.saturating_add(1)
    } else {
        time_ms.saturating_add(skill.focus_time_ms as u64)
    };
    if let Some(caster) = self.units.get_mut(&caster_instance_id) {
        caster.next_action_time = cast_end_ms;
        caster.action_locks.lock_resonance_gain_until(cast_end_ms);
        if !skill.focus_permissions.allows_basic_attack {
            caster.action_locks.lock_basic_attack_until(cast_end_ms);
        }
        if !skill.focus_permissions.allows_move {
            caster.action_locks.lock_movement_until(cast_end_ms);
        }
    }

    if !skill.focus_permissions.allows_move {
        let interrupted = self.interrupt_movement(
            time_ms,
            caster_instance_id,
            crate::game::battle::event_log::MovementStopReason::CastStarted,
            Some(cast_end_ms),
            ActionState::Idle,
        );
        if interrupted {
            self.schedule_continuous_movement_tick(cast_end_ms);
        }
    }

    let start_seq = self.record_event_log(
        time_ms,
        BattleLogEvent::ManualCastStart {
            skill_id: skill.id.clone(),
            caster_instance_id,
            target: cast_target,
        },
    );
    let accepted_target_tile = match cast_target {
        Some(SkillCastTarget::Unit { unit_instance_id }) => {
            self.live_unit_projected_tile(unit_instance_id)
        }
        Some(SkillCastTarget::Tile { position }) => Some(position),
        _ => None,
    };
    if let Some(caster) = self.units.get_mut(&caster_instance_id) {
        caster.pending_skill_cast = Some(PendingSkillCast {
            skill_id: skill.id,
            cast_target,
            accepted_target_tile,
            start_seq,
        });
    }
    self.event_queue.push(BattleEvent::ManualCastEnd {
        time_ms: cast_end_ms,
        caster_instance_id,
        cause: BattleEventCause::Parent { seq: start_seq },
    });

    Ok(())
}

    if self.event_queue.iter().any(
        |event| matches!(event, BattleEvent::ContinuousMovementTick { time_ms: queued } if *queued == time_ms),
    ) {
        return;
    }

    self.event_queue
        .push(BattleEvent::ContinuousMovementTick { time_ms });
}

