        let equipment = game_data
            .equipment_data
            .get_by_uuid(&equipped.base_uuid)
            .ok_or(GameError::MissingResource("EquipmentMetadata"))?;
        if equipment.equipment_type != crate::game::data::equipment_data::EquipmentType::Weapon {
